     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
     4→import { useAtomValue } from "jotai";
     5→import { TimelineAtoms } from "modules/timeline/jotai";
     6→import { type FC, useEffect, useState } from "react";
     7→import { FlatList, StyleSheet } from "react-native";
     8→import { SingleMessageType } from "screens/room/fragments";
     9→import { GoBackHeader, Loading } from "shared/components";
    10→import { ScreenLayout } from "shared/components/screen-layout/ScreenLayout";
    11→import { Colors, TextSize } from "shared/styles";
    12→
    13→const keyExtractor = (item: EventTimelineItem) => {
    14→  const eventId = item.eventOrTransactionId;
    15→  if (eventId?.tag === "EventId") {
    16→    return eventId.inner.eventId;
    17→  }
    18→  if (eventId?.tag === "TransactionId") {
    19→    return eventId.inner.transactionId;
    20→  }
    21→  return String(item.timestamp);
    22→};
    23→
    24→export const PinnedEvents: FC<
    25→  NativeStackScreenProps<Routes, "pinnedEvents">
    26→> = ({ route }) => {
    27→  const { room } = route.params;
    28→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
    29→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    30→  const [loading, setLoading] = useState(true);
    31→
    32→  useEffect(() => {
    33→    if (!room) return;
    34→
    35→    setEvents([]);
    36→
    37→    const initPinnedTimeline = async () => {
    38→      try {
    39→        if (pinnedEventIds.length === 0) {
    40→          setEvents([]);
    41→          setLoading(false);
    42→          return;
    43→        }
    44→
    45→        const timeline = await room.timeline();
    46→        const fetchedEvents: EventTimelineItem[] = [];
    47→
    48→        for (const id of pinnedEventIds) {
    49→          try {
    50→            await timeline.fetchDetailsForEvent(id);
    51→            const item = await timeline.getEventTimelineItemByEventId(id);
    52→            if (item) {
    53→              fetchedEvents.push(item);
    54→            }
    55→          } catch (error) {
    56→            console.warn("Failed to load pinned event:", id, error);
    57→          }
    58→        }
    59→
    60→        setEvents(fetchedEvents);
    61→        setLoading(false);
    62→      } catch (error) {
    63→        console.error("Failed to initialize pinned events timeline:", error);
    64→        setLoading(false);
    65→      }
    66→    };
    67→
    68→    initPinnedTimeline();
    69→
    70→    return () => {};
    71→  }, [room]);
    72→
    73→  return (
    74→    <ScreenLayout type="modal">
    75→      <GoBackHeader title="Pinned Events" margins={{ marginBottom: 20 }} />
    76→      <FlatList
    77→        data={events}
    78→        renderItem={({ item }) => {
    79→          return (
    80→            <Block paddings={{ paddingHorizontal: 16 }}>
    81→              <SingleMessageType event={item} isPreviousSameSender={false} />
    82→            </Block>
    83→          );
    84→        }}
    85→        keyExtractor={keyExtractor}
    86→        contentContainerStyle={styles.listContent}
    87→        ListEmptyComponent={
    88→          <Block align="center" justify="center" flex={1} paddings={40}>
    89→            {loading ? (
    90→              <Loading isFullScreen={false} />
    91→            ) : (
    92→              <Text size={TextSize.medium} color={Colors.white50}>
    93→                No pinned events
    94→              </Text>
    95→            )}
    96→          </Block>
    97→        }
    98→        showsVerticalScrollIndicator={false}
    99→      />
   100→    </ScreenLayout>
   101→  );
   102→};
   103→
   104→const styles = StyleSheet.create({
   105→  listContent: {
   106→    flexGrow: 1,
   107→    paddingBottom: 20,
   108→  },
   109→});
