     1→import type {
     2→  EventTimelineItem,
     3→  RoomInterface,
     4→  TaskHandleInterface,
     5→  TimelineInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import {
     8→  DateDividerMode,
     9→  MessageType_Tags,
    10→  MsgLikeKind_Tags,
    11→  ReceiptType,
    12→  TimelineDiff_Tags,
    13→  TimelineFilter,
    14→  TimelineFocus,
    15→  TimelineItemContent_Tags,
    16→  TimelineReadReceiptTracking,
    17→} from "@unomed/react-native-matrix-sdk";
    18→import { useSetAtom } from "jotai";
    19→import { MatrixAtoms } from "modules/matrix-client/jotai";
    20→import { getEventId } from "modules/matrix-client/utils";
    21→import { NavigationContainerRef } from "modules/navigation/const";
    22→import { TimelineAtoms } from "modules/timeline";
    23→import { TimelineService } from "modules/timeline/service/TimelineService";
    24→import { useCallback, useEffect, useRef, useState } from "react";
    25→import Toast from "react-native-toast-message";
    26→
    27→/** Maximum age for a verification request to be considered valid (5 minutes) */
    28→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
    29→
    30→/** Check if an event is a verification request */
    31→const isVerificationRequest = (event: EventTimelineItem): boolean => {
    32→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
    33→  const kind = event.content.inner.content.kind;
    34→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
    35→  const msgType = kind.inner.content.msgType;
    36→  return (
    37→    msgType?.tag === MessageType_Tags.Other &&
    38→    msgType.inner.msgtype === "m.key.verification.request"
    39→  );
    40→};
    41→
    42→/** Check if a verification request is recent enough to be handled */
    43→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
    44→  const eventTimestamp = Number(event.timestamp);
    45→  const now = Date.now();
    46→  const age = now - eventTimestamp;
    47→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
    48→};
    49→
    50→interface Props {
    51→  room: RoomInterface | undefined;
    52→  roomId: string;
    53→}
    54→
    55→export const useRoomTimeline = ({ room, roomId }: Props) => {
    56→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    57→  const [loadingMessage, setLoadingMessage] = useState(true);
    58→  /** Track processed verification request IDs to avoid duplicates */
    59→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
    60→  const [refreshing, setRefreshing] = useState(false);
    61→  const [updateTrigger, setUpdateTrigger] = useState(0);
    62→  const eventIdsRef = useRef<Set<string>>(new Set());
    63→  const timelineRef = useRef<TimelineInterface | null>(null);
    64→  const isPaginatingRef = useRef(false);
    65→  const timelinePaginateNumber = useRef<number>(20);
    66→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    67→  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
    68→  const [isDirect, setIsDirect] = useState(false);
    69→
    70→  const upsertEvents = (
    71→    incoming: EventTimelineItem[],
    72→    position: "front" | "back" = "back",
    73→  ) => {
    74→    setEvents((prev) => {
    75→      const next = [...prev];
    76→      for (const e of incoming) {
    77→        const id = getEventId(e);
    78→        if (!id) continue;
    79→        const existingIndex = next.findIndex((item) => getEventId(item) === id);
    80→        if (existingIndex !== -1) {
    81→          next[existingIndex] = e;
    82→          continue;
    83→        }
    84→
    85→        eventIdsRef.current.add(id);
    86→        if (position === "front") next.unshift(e);
    87→        else next.push(e);
    88→      }
    89→      return next;
    90→    });
    91→  };
    92→
    93→  const handleVerificationRequest = (info: {
    94→    senderId: string;
    95→    flowId: string;
    96→  }) => {
    97→    setVerificationStatus("incomingRequest");
    98→    NavigationContainerRef.navigate("verifyUser", {
    99→      userId: info.senderId,
   100→      flowId: info.flowId,
   101→    });
   102→  };
   103→
   104→  const checkForVerificationRequests = useCallback(
   105→    (incoming: EventTimelineItem[]) => {
   106→      for (const event of incoming) {
   107→        if (event.isOwn) continue;
   108→
   109→        if (
   110→          !isVerificationRequest(event) ||
   111→          !isRecentVerificationRequest(event)
   112→        ) {
   113→          continue;
   114→        }
   115→
   116→        const flowId = getEventId(event);
   117→        if (!flowId) continue;
   118→
   119→        if (processedVerificationRequestsRef.current.has(flowId)) continue;
   120→
   121→        processedVerificationRequestsRef.current.add(flowId);
   122→
   123→        handleVerificationRequest({
   124→          senderId: event.sender,
   125→          flowId,
   126→        });
   127→
   128→        // Only handle one at a time
   129→        break;
   130→      }
   131→    },
   132→    [],
   133→  );
   134→
   135→  const markAsRead = async () => {
   136→    if (!room) return;
   137→
   138→    try {
   139→      await room.markAsRead(ReceiptType.Read);
   140→    } catch (error) {
   141→      console.error("Failed to mark room as read:", error);
   142→    }
   143→  };
   144→
   145→  const loadMoreMessages = async () => {
   146→    if (!room || !timelineRef.current) return;
   147→
   148→    isPaginatingRef.current = true;
   149→    setRefreshing(true);
   150→
   151→    try {
   152→      await timelineRef.current.paginateBackwards(
   153→        timelinePaginateNumber.current,
   154→      );
   155→      timelinePaginateNumber.current += 20;
   156→    } catch (error) {
   157→      console.error("Failed to load more messages:", error);
   158→    } finally {
   159→      setRefreshing(false);
   160→      isPaginatingRef.current = false;
   161→    }
   162→  };
   163→
   164→  useEffect(() => {
   165→    if (!room) return;
   166→    setPinnedEventIds([]);
   167→    TimelineService.getPinnedEventIds(roomId)
   168→      .then(setPinnedEventIds)
   169→      .catch(console.error);
   170→  }, [roomId]);
   171→
   172→  useEffect(() => {
   173→    if (!room) return;
   174→
   175→    // Reset state when room changes
   176→    setEvents([]);
   177→    eventIdsRef.current.clear();
   178→
   179→    let timelineListenerHandle: TaskHandleInterface | null = null;
   180→
   181→    const initRoomTimeline = async () => {
   182→      try {
   183→        const timeline = await room.timelineWithConfiguration({
   184→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
   185→          filter: new TimelineFilter.All(),
   186→          internalIdPrefix: undefined,
   187→          dateDividerMode: DateDividerMode.Daily,
   188→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
   189→          reportUtds: false,
   190→        });
   191→
   192→        // Store timeline in ref for reuse in pagination
   193→        timelineRef.current = timeline;
   194→
   195→        await timeline.paginateBackwards(timelinePaginateNumber.current);
   196→        timelinePaginateNumber.current += 20;
   197→        setLoadingMessage(false);
   198→
   199→        // Set up timeline listener for real-time updates
   200→        timelineListenerHandle = await timeline.addListener({
   201→          onUpdate: (diffs) => {
   202→            markAsRead();
   203→            // Trigger re-render to update read receipts and other event properties
   204→            setUpdateTrigger((prev) => prev + 1);
   205→            diffs.forEach((diff) => {
   206→              const change = diff.tag;
   207→              switch (change) {
   208→                case TimelineDiff_Tags.Append: {
   209→                  const newItems = diff.inner.values;
   210→                  if (newItems.length) {
   211→                    const eventItems = newItems
   212→                      .map((i) => i.asEvent())
   213→                      .filter((i): i is EventTimelineItem => !!i);
   214→
   215→                    if (eventItems.length > 0) {
   216→                      upsertEvents(eventItems, "back");
   217→                      checkForVerificationRequests(eventItems);
   218→                    }
   219→                  }
   220→                  break;
   221→                }
   222→                case TimelineDiff_Tags.Insert: {
   223→                  const { value } = diff.inner;
   224→                  const ev = value.asEvent();
   225→                  if (ev) {
   226→                    upsertEvents([ev], "back");
   227→                    checkForVerificationRequests([ev]);
   228→                  }
   229→                  break;
   230→                }
   231→                case TimelineDiff_Tags.Set: {
   232→                  const { value } = diff.inner;
   233→                  const ev = value.asEvent();
   234→                  if (ev) {
   235→                    const id = getEventId(ev);
   236→                    if (!id) break;
   237→
   238→                    setEvents((prev) => {
   239→                      // Find event by ID to handle edits/deletions properly
   240→                      const existingIndex = prev.findIndex(
   241→                        (e) => getEventId(e) === id,
   242→                      );
   243→                      if (existingIndex !== -1) {
   244→                        const next = [...prev];
   245→                        next[existingIndex] = ev;
   246→                        return next;
   247→                      }
   248→                      // If not found and not tracked, add it
   249→                      if (!eventIdsRef.current.has(id)) {
   250→                        eventIdsRef.current.add(id);
   251→                        return [...prev, ev];
   252→                      }
   253→                      return prev;
   254→                    });
   255→                  }
   256→                  break;
   257→                }
   258→                case TimelineDiff_Tags.Remove: {
   259→                  const { index: removeIndex } = diff.inner;
   260→                  setEvents((prev) => {
   261→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   262→                    eventIdsRef.current = new Set(
   263→                      next.map(getEventId).filter(Boolean) as string[],
   264→                    );
   265→                    return next;
   266→                  });
   267→                  break;
   268→                }
   269→                case TimelineDiff_Tags.PushFront: {
   270→                  const { value } = diff.inner;
   271→                  const ev = value.asEvent();
   272→                  if (ev) {
   273→                    upsertEvents([ev], "front");
   274→                    checkForVerificationRequests([ev]);
   275→                  }
   276→                  break;
   277→                }
   278→                case TimelineDiff_Tags.PushBack: {
   279→                  const { value } = diff.inner;
   280→                  const ev = value.asEvent();
   281→                  if (ev) {
   282→                    upsertEvents([ev], "back");
   283→                    checkForVerificationRequests([ev]);
   284→                  }
   285→                  break;
   286→                }
   287→                case TimelineDiff_Tags.Reset: {
   288→                  const resetItems = diff.inner.values;
   289→                  if (resetItems.length) {
   290→                    const eventItems = resetItems
   291→                      .map((i) => i.asEvent())
   292→                      .filter((i): i is EventTimelineItem => !!i);
   293→
   294→                    // Deduplicate events in case Reset contains duplicates
   295→                    const seenIds = new Set<string>();
   296→                    const uniqueEvents: EventTimelineItem[] = [];
   297→
   298→                    for (const event of eventItems) {
   299→                      const id = getEventId(event);
   300→                      if (id && !seenIds.has(id)) {
   301→                        seenIds.add(id);
   302→                        uniqueEvents.push(event);
   303→                      }
   304→                    }
   305→
   306→                    eventIdsRef.current = seenIds;
   307→                    setEvents(uniqueEvents);
   308→                  }
   309→                  break;
   310→                }
   311→                case TimelineDiff_Tags.Truncate: {
   312→                  const { length: cut } = diff.inner;
   313→                  setEvents((prev) => {
   314→                    const next = prev.slice(0, cut);
   315→                    eventIdsRef.current = new Set(
   316→                      next.map(getEventId).filter(Boolean) as string[],
   317→                    );
   318→                    return next;
   319→                  });
   320→                  break;
   321→                }
   322→                default:
   323→                  console.log("Unknown timeline change type:", change);
   324→              }
   325→            });
   326→          },
   327→        });
   328→      } catch (error) {
   329→        console.error("Failed to initialize room timeline:", error);
   330→        Toast.show({
   331→          text1: "Failed to load the messages. Please try again.",
   332→          type: "error",
   333→        });
   334→        NavigationContainerRef.goBack();
   335→        return null;
   336→      }
   337→    };
   338→
   339→    initRoomTimeline();
   340→
   341→    return () => {
   342→      timelineListenerHandle?.cancel?.();
   343→      timelineRef.current = null;
   344→    };
   345→  }, [roomId, checkForVerificationRequests]);
   346→
   347→  useEffect(() => {
   348→    markAsRead().catch(console.error);
   349→    room?.isDirect().then(setIsDirect).catch(console.error);
   350→  }, []);
   351→
   352→  return {
   353→    events,
   354→    loadingMessage,
   355→    refreshing,
   356→    timelineRef,
   357→    isPaginatingRef,
   358→    updateTrigger,
   359→    isDirect,
   360→    loadMoreMessages,
   361→    markAsRead,
   362→  };
   363→};
   364→

