   340→  public static getReadReceipts = async (event: EventTimelineItem) => {
   341→    const userIds = Array.from(event.readReceipts.keys());
   342→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
   343→
   344→    if (!filteredUserIds.length) return [];
   345→
   346→    try {
   347→      const client = MatrixCore.getClient();
   348→      const profilePromises = filteredUserIds.map((userId) =>
   349→        client.getProfile(userId),
   350→      );
   351→      const profiles = await Promise.allSettled(profilePromises);
   352→      return profiles
   353→        .filter((p) => p.status === "fulfilled")
   354→        .map((p) => p.value)
   355→        .filter((p) => p !== undefined);
   356→    } catch (error) {
   357→      console.error("Failed to get read receipt users:", error);
   358→      return [];
   359→    }
   360→  };
