    33→      if (msgType?.tag === MessageType_Tags.Text) {
    34→        messageBody = kind.inner.content.body || "";
    35→      } else if (msgType?.tag === MessageType_Tags.Emote) {
    36→        messageBody = kind.inner.content.body || "Emote";
    37→      } else if (msgType?.tag === MessageType_Tags.Image) {
    38→        messageBody = "📷 Image";
    39→      } else if (msgType?.tag === MessageType_Tags.File) {
    40→        messageBody = "📎 File";
    41→      } else if (msgType?.tag === MessageType_Tags.Video) {
    42→        messageBody = "🎥 Video";
    43→      } else if (msgType?.tag === MessageType_Tags.Audio) {
    44→        messageBody = "🎵 Audio";
    45→      } else if (msgType?.tag === MessageType_Tags.Gallery) {
    46→        messageBody = "🖼️ Gallery";
    47→      } else if (msgType?.tag === MessageType_Tags.Notice) {
    48→        messageBody = kind.inner.content.body || "Notice";
    49→      } else if (msgType?.tag === MessageType_Tags.Location) {
    50→        messageBody = "📍 Location";
    51→      } else if (msgType?.tag === MessageType_Tags.Other) {
    52→        messageBody = "Message";
    53→      } else {
    54→        messageBody = "Message";
    55→      }
    56→    }
    57→
    58→    if (kind?.tag === MsgLikeKind_Tags.Sticker) {
    59→      messageBody = "🧩 Sticker";
    60→    } else if (kind?.tag === MsgLikeKind_Tags.Poll) {
    61→      messageBody = "📊 Poll";
    62→    } else if (kind?.tag === MsgLikeKind_Tags.Redacted) {
    63→      messageBody = "Message deleted";
    64→    } else if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
    65→      messageBody = "Unable to decrypt message";
    66→    } else if (kind?.tag === MsgLikeKind_Tags.Other) {
    67→      messageBody = "Message";
    68→    }
    69→
    70→    return `${senderName}: ${messageBody || "Message"}`;
    71→  }
    72→
    73→  if (type === TimelineItemContent_Tags.RoomMembership) {
    74→    return `${senderName}: Room name changed`;
    75→  }
    76→
    77→  if (type === TimelineItemContent_Tags.ProfileChange) {
    78→    return `${senderName}: Personal settings changed`;
    79→  }
    80→
    81→  if (type === TimelineItemContent_Tags.State) {
    82→    const stateContent = event?.content.inner.content;
    83→    if (stateContent?.tag === OtherState_Tags.RoomName) {
    84→      return `${senderName}: Room name changed`;
    85→    }
    86→    if (stateContent?.tag === OtherState_Tags.RoomTopic) {
    87→      const topic = stateContent.inner.topic;
    88→      return topic
    89→        ? `${senderName}: Room topic changed to ${topic}`
    90→        : `${senderName}: Room topic changed`;
    91→    }
    92→    if (stateContent?.tag === OtherState_Tags.RoomAvatar) {
    93→      return `${senderName}: Room avatar changed`;
    94→    }
    95→    if (stateContent?.tag === OtherState_Tags.RoomEncryption) {
    96→      return `${senderName}: Room encryption changed`;
    97→    }
    98→    if (stateContent?.tag === OtherState_Tags.RoomJoinRules) {
    99→      return `${senderName}: Room join rules changed`;
   100→    }
   101→    if (stateContent?.tag === OtherState_Tags.RoomHistoryVisibility) {
   102→      return `${senderName}: Room history visibility changed`;
   103→    }
   104→    if (stateContent?.tag === OtherState_Tags.PolicyRuleRoom) {
