     1→import { useIsFocused } from "@react-navigation/native";
     2→import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
     3→import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
     4→import { useEffect, useMemo, useState } from "react";
     5→
     6→interface UseRoomInitializationProps {
     7→  room: RoomInterface | undefined;
     8→}
     9→
    10→export const useRoomInitialization = ({ room }: UseRoomInitializationProps) => {
    11→  const [isEncrypted, setIsEncrypted] = useState(false);
    12→  const [roomMembers, setRoomMembers] = useState(0);
    13→  const isFocused = useIsFocused();
    14→  const [isMembersLoading, setIsMembersLoading] = useState(true);
    15→  const hasNoCallOption = useMemo(() => {
    16→    return (room?.isPublic() && !isEncrypted) || !isEncrypted;
    17→  }, [room, isEncrypted, isFocused]);
    18→
    19→  useEffect(() => {
    20→    if (!room) return;
    21→
    22→    room.isEncrypted().then(setIsEncrypted).catch(console.error);
    23→    room
    24→      .members()
    25→      .then((info) => {
    26→        const members = info.nextChunk(1000) ?? [];
    27→        const acceptedMembers = members.filter(
    28→          (member) => member.membership?.tag === MembershipState_Tags.Join,
    29→        );
    30→        setRoomMembers(acceptedMembers.length);
    31→      })
    32→      .catch(console.error)
    33→      .finally(() => setIsMembersLoading(false));
    34→  }, [room, isFocused]);
    35→
    36→  return {
    37→    isMembersLoading,
    38→    isEncrypted,
    39→    roomMembers,
    40→    hasNoCallOption,
    41→  };
    42→};
